import sys
import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def is_fibonacci(n):
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True

    a, b = 0, 1
    while b < n:
        a, b = b, a + b
    return b == n

def main():
    line = sys.stdin.readline()
    if not line:
        return
    line = line.strip()
    if not line:
        return

    n = int(line)

    if is_prime(n) and is_fibonacci(n):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
